var n=`1320-pastel-de-choclo`;var t=`world-1320`;var a=`CL`;var o=`south-america`;var r=8;var s=109;var l={en:`Pastel de Choclo`,ua:`Пастель де чокло`};var d={en:`Pastel de Choclo is a dish from Chile featuring ground beef, yellow onion, garlic, raisin. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пастель де чокло, страва кухні країни Чилі з такими основними складниками: яловичий фарш, жовта цибуля, часник, родзинки. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`ground-beef`,570,`g`],[`yellow-onion`,210,`g`],[`garlic`,5,`clove`],[`ground-cumin`,6,`g`],[`raisin`,70,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 18 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 18 хвилин до готовності й м’якості.`,t:[`poaching`],m:18,i:[[`chicken-thigh`,420,`g`],[`water`,450,`ml`]]},{en:`Boil the eggs for about 11 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 11 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:11,i:[[`chicken-egg`,3,`pcs`]]},{en:`Blend the corn with milk and butter into a thick corn topping. Place fully cooked pino, chicken and hard-boiled eggs below the corn layer.`,ua:`Подрібніть кукурудзу з молоком і маслом на густу масу. Викладіть повністю готову начинку піно, курку та варені яйця під кукурудзяний шар.`,t:[`pureeing`],m:8,i:[[`fresh-corn-kernels`,850,`g`],[`whole-cow-milk`,260,`ml`],[`unsalted-butter`,55,`g`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:12,i:[[`green-olives`,90,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 46 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 46 хвилин до готовності.`,t:[`baking`],m:46,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`white-granulated-sugar`,25,`g`]]}];var h={slug:n,id:t,country:`CL`,region:o,servings:8,minutes:109,title:l,text:d,steps:g};export{a as country,h as default,t as id,s as minutes,o as region,r as servings,n as slug,g as steps,d as text,l as title};